create table if not exists artifacts(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,project_id uuid references projects(id) on delete cascade,type text not null,storage_bucket text,storage_path text not null,version int not null default 1,checksum text,size bigint,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists artifact_versions(id uuid primary key default gen_random_uuid(),artifact_id uuid not null references artifacts(id) on delete cascade,version int not null,storage_path text not null,checksum text,size bigint,created_at timestamptz not null default now(),unique(artifact_id,version));
